package com.paytaxihub.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity @Table(name="Wallet") public class Wallet { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Integer walletId; @OneToOne @JoinColumn(name="user_id") private User user; private BigDecimal balance; @Enumerated(EnumType.STRING) private WalletStatus walletStatus; private LocalDateTime createdAt; public enum WalletStatus{Active,Suspended} public Wallet(){} public Integer getWalletId(){return walletId;} public void setWalletId(Integer v){walletId=v;} public User getUser(){return user;} public void setUser(User v){user=v;} public BigDecimal getBalance(){return balance;} public void setBalance(BigDecimal v){balance=v;} public WalletStatus getWalletStatus(){return walletStatus;} public void setWalletStatus(WalletStatus v){walletStatus=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;} }
